from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class CounterValuePMV2(SchemaObject):
    value = SchemaField(name="value")
    start_time = SchemaField(name="startTime")

    def __init__(self, value, start_time):
        self.value = value
        self.start_time = start_time
        super(CounterValuePMV2, self).__init__()
